import { relations } from "drizzle-orm";
import {
  boolean,
  integer,
  pgTable,
  unique,
  varchar,
} from "drizzle-orm/pg-core";
import { school } from "./school";
import { studentProfile } from "./student-profile";

/*
CREATE TABLE "department" (
    "pk"        integer     GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "school_pk" integer     NOT NULL REFERENCES "school" ("pk"),
    "name"      varchar(64) NOT NULL,
    "is_active" boolean     NOT NULL DEFAULT true,
    UNIQUE ("school_pk", "name")
);
*/
// 기준 데이터. 어드민에서 추가 · 수정. 학과명이 바뀌면 같은 행의 name만 수정 (버전 관리 안 함)
// 학생 프로필이 참조하므로 지우지 않고 비활성화함
export const department = pgTable(
  "department",
  {
    pk: integer("pk").primaryKey().generatedByDefaultAsIdentity().notNull(),
    schoolPk: integer("school_pk")
      .notNull()
      .references(() => school.pk),
    name: varchar("name", { length: 64 }).notNull(),
    // false면 목록에서 숨기고 새로 고를 수 없음. 이미 고른 학생은 그대로 유지
    isActive: boolean("is_active").notNull().default(true),
  },
  (table) => [
    unique("department_school_pk_name_unique").on(table.schoolPk, table.name),
  ],
);

export const departmentRelations = relations(department, ({ one, many }) => ({
  school: one(school, {
    fields: [department.schoolPk],
    references: [school.pk],
  }),
  studentProfiles: many(studentProfile),
}));
